parent = hou.node("/obj/alien_spaceship_main")
# Find key structural nodes: nulls (named ones are usually section markers), output, merges
nulls = []
for child in parent.children():
    if child.type().name() == "null":
        nulls.append({"name": child.name(), "pos": list(child.position()), 
                       "inputs": [i.name() for i in child.inputs() if i],
                       "outputs": [o.name() for o in child.outputs() if o]})

# Find display/render flagged nodes
flagged = []
for child in parent.children():
    if hasattr(child, 'isDisplayFlagSet') and child.isDisplayFlagSet():
        flagged.append({"name": child.name(), "type": child.type().name(), "display": True})
    if hasattr(child, 'isRenderFlagSet') and child.isRenderFlagSet():
        flagged.append({"name": child.name(), "type": child.type().name(), "render": True})

import json
result = {"nulls": nulls, "flagged": flagged}
json.dumps(result)
